<script setup lang="ts">
import { ref } from 'vue'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { api } from '../api'

const client = useQueryClient()
const stage = ref(''), status = ref(''), cursor = ref<string>()
const jobs = useQuery({ queryKey: ['jobs', stage, status, cursor], queryFn: () => api.jobs({ stage: stage.value || undefined, status: status.value || undefined, cursor: cursor.value }), refetchInterval: 5000 })
const backlog = useQuery({ queryKey: ['jobs-backlog'], queryFn: api.backlog, refetchInterval: 5000, retry: false })
const retry = useMutation({ mutationFn: api.retryJob, onSuccess: () => { client.invalidateQueries({ queryKey: ['jobs'] }); client.invalidateQueries({ queryKey: ['jobs-backlog'] }) } })
const indexing = useQuery({ queryKey: ['indexing-status'], queryFn: api.indexingStatus, refetchInterval: 5000, retry: false })
const failures = useQuery({ queryKey: ['indexing-failures'], queryFn: () => api.indexingFailures(), refetchInterval: 5000, retry: false })
const retryIndexing = useMutation({ mutationFn: (articleId: string) => api.retryIndexing(articleId), onSuccess: () => { client.invalidateQueries({ queryKey: ['indexing-status'] }); client.invalidateQueries({ queryKey: ['indexing-failures'] }) } })
const nlp = useQuery({ queryKey: ['nlp-status'], queryFn: api.nlpStatus, refetchInterval: 5000, retry: false })
const nlpFailures = useQuery({ queryKey: ['nlp-failures'], queryFn: () => api.nlpFailures(), refetchInterval: 5000, retry: false })
const retryNlp = useMutation({ mutationFn: (jobId: string) => api.retryNlpJob(jobId), onSuccess: () => { client.invalidateQueries({ queryKey: ['nlp-status'] }); client.invalidateQueries({ queryKey: ['nlp-failures'] }) } })
function setStage(event: Event) { cursor.value = undefined; stage.value = (event.target as HTMLSelectElement).value }
function setStatus(event: Event) { cursor.value = undefined; status.value = (event.target as HTMLSelectElement).value }
</script>

<template><header><div><p class="eyebrow">Article processing</p><h2>Jobs</h2></div></header>
  <p v-if="backlog.isPending.value" class="muted">Loading backlog…</p><p v-else-if="backlog.isError.value" class="error">Could not load backlog.</p><div v-else class="backlog"><span>Queued <strong>{{ backlog.data.value?.queued || 0 }}</strong></span><span>Running <strong>{{ backlog.data.value?.running || 0 }}</strong></span><span>Retrying <strong>{{ backlog.data.value?.retrying || 0 }}</strong></span><span>Failed <strong>{{ backlog.data.value?.failed || 0 }}</strong></span></div>
  <div class="job-filters"><label>Stage<select :value="stage" @change="setStage"><option value="">All stages</option><option value="fetch">Fetch</option><option value="extract">Extract</option></select></label><label>Status<select :value="status" @change="setStatus"><option value="">All statuses</option><option v-for="value in ['queued', 'running', 'retrying', 'succeeded', 'failed']" :key="value" :value="value">{{ value }}</option></select></label></div>
  <section class="panel jobs"><p v-if="jobs.isPending.value" class="muted">Loading processing jobs…</p><p v-else-if="jobs.isError.value" class="error">Could not load processing jobs.</p><p v-else-if="!jobs.data.value?.items.length" class="muted">No processing jobs.</p><p v-if="retry.isPending.value" class="muted">Retrying job…</p><p v-if="retry.isSuccess.value" class="success">Retry scheduled.</p><p v-if="retry.isError.value" class="error">Could not retry the job.</p><article v-for="job in jobs.data.value?.items" :key="job.id" class="job-row"><div><strong>{{ job.article_title }}</strong><small>{{ job.stage }} · {{ job.requested_mode.split('_').join(' ') }}</small></div><span :class="['badge', job.status === 'succeeded' ? 'healthy' : 'pending']">{{ job.status }}</span><p v-if="job.error_message" class="error">{{ job.error_category }}: {{ job.error_message }}</p><details v-if="(job.attempts || []).length"><summary>{{ (job.attempts || []).length }} attempts</summary><p v-for="attempt in (job.attempts || [])" :key="attempt.id" class="muted">{{ attempt.stage }} #{{ attempt.attempt_number }} — {{ attempt.status }}<span v-if="attempt.error_message">: {{ attempt.error_message }}</span></p></details><button v-if="job.status === 'failed'" class="secondary" :disabled="retry.isPending.value" @click="retry.mutate(job.id)">Retry</button></article><button v-if="jobs.data.value?.next_cursor" class="secondary" @click="cursor = jobs.data.value.next_cursor || undefined">Next page</button></section>
  <section class="panel indexing"><h3>Search indexing</h3><p v-if="indexing.isPending.value" class="muted">Loading indexing status…</p><p v-else-if="indexing.isError.value" class="error">Could not load indexing status.</p><div v-else class="backlog"><span>Queued <strong>{{ indexing.data.value?.queued || 0 }}</strong></span><span>Running <strong>{{ indexing.data.value?.running || 0 }}</strong></span><span>Retrying <strong>{{ indexing.data.value?.retrying || 0 }}</strong></span><span>Failed <strong>{{ indexing.data.value?.failed || 0 }}</strong></span></div><p v-if="indexing.data.value?.active_rebuild" class="muted">An index rebuild is active.</p><p v-if="retryIndexing.isPending.value" class="muted">Scheduling indexing retry…</p><p v-if="retryIndexing.isSuccess.value" class="success">Indexing retry scheduled.</p><p v-if="retryIndexing.isError.value" class="error">Could not retry indexing.</p><p v-if="failures.isError.value" class="error">Could not load indexing failures.</p><article v-for="failure in failures.data.value?.items" :key="failure.id" class="job-row"><div><strong>{{ failure.article_id }}</strong><small>{{ failure.index_name }} · {{ failure.attempt_count }} attempts</small></div><p class="error">{{ failure.error_category }}: {{ failure.error_message }}</p><button class="secondary" :disabled="retryIndexing.isPending.value" @click="retryIndexing.mutate(failure.article_id)">Retry indexing</button></article></section>
  <section class="panel indexing"><h3>NLP processing</h3><p v-if="nlp.isPending.value" class="muted">Loading NLP status…</p><p v-else-if="nlp.isError.value" class="error">Could not load NLP status.</p><template v-else><div class="backlog"><span>Queued <strong>{{ nlp.data.value?.queued || 0 }}</strong></span><span>Running <strong>{{ nlp.data.value?.running || 0 }}</strong></span><span>Retrying <strong>{{ nlp.data.value?.retrying || 0 }}</strong></span><span>Failed <strong>{{ nlp.data.value?.failed || 0 }}</strong></span></div><p v-for="capability in nlp.data.value?.capabilities" :key="capability.name" class="muted">{{ capability.name }} · {{ capability.state }}<span v-if="capability.version"> · {{ capability.version }}</span><span v-if="capability.detail"> · {{ capability.detail }}</span></p><p v-for="run in nlp.data.value?.reprocessing" :key="String(run.id)" class="muted">Reprocessing {{ run.status }} · {{ run.scanned || 0 }} articles scanned</p></template><p v-if="retryNlp.isPending.value" class="muted">Scheduling NLP retry…</p><p v-if="retryNlp.isSuccess.value" class="success">NLP retry scheduled.</p><p v-if="retryNlp.isError.value" class="error">Could not retry NLP processing.</p><p v-if="nlpFailures.isError.value" class="error">Could not load NLP failures.</p><article v-for="failure in nlpFailures.data.value?.items" :key="failure.id" class="job-row"><div><strong>{{ failure.article_id }}</strong><small>{{ failure.processor }} · {{ failure.attempt_count }} attempts</small></div><p class="error">{{ failure.error_category }}: {{ failure.error_message }}</p><button class="secondary" :disabled="retryNlp.isPending.value" @click="retryNlp.mutate(failure.id)">Retry NLP</button></article></section>
</template>
